.fplink.image .image {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  font-size: 75%;
  z-index: 1;
}

.fplink.image a {
  z-index: 2;
}

.fplink a {
  display: block;
  position: relative;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 1px 5px;
}

.fplink.image .image a {
  padding: 0;
}

.fplink.image .link a {
  background: rgba(255,255,255,.75);
  border-top: 2px solid #505050;
}

.fplink.wide a {
  margin: 0 -5px;
}

.fpvideos {
  margin: 0 auto;
  overflow: hidden;
  text-align: center;
}

.fpvideo {
  display: inline-block;
  margin: 0 5px;
}



/* Infoboxes */

.infoboxtable {
    float: right;
    background:rgba(255,255,255,.75);
    border: 1px solid #FC6600;
    border-radius:5px;
    width: 350px;
}

.infoboxname {
    background:#FC6600;
    color: #fff;
    font-size: 115%;
    border: 1px solid #FC6600;
    border-radius:5px;
}

.infoboxlabel {
    width: 50%;
    background:#000;
    color: #fff;
    border: 1px solid #FC6600;
    border-radius:5px;
    padding: 0.5px 7px;
    text-align: right;
}


.infoboxdetails {
    padding-right: 5px;
}

/* Newer Navbox template style */
table.navbox {
    border: 1px solid #aaa;
    clear: both;
    font-size: 88%;
    margin: auto;
    padding: 1px;
    text-align: center;
    width: 100%; 
}

/* Border between adjacent navboxes */
table.navbox + table.navbox {
    margin-top: -1px;
}

.navbox-title,
.navbox-abovebelow,
table.navbox th {
    padding-left: 1em;
    padding-right: 1em;
    text-align: center;
}

.navbox-group {
    font-weight: bold;
    padding-left: 1em;
    padding-right: 1em;
    white-space: nowrap;
}

/* Base background */
.navbox, .navbox-subgroup {
    background: #fff;
}

.navbox-list {
    border-color: #fff;   /* Must match background color */
}

/* Level 1 color */
.navbox-title,
table.navbox th {
    background: #fff;
    border: 1px solid #aaa;
    color: #000;
}

/* Level 2 styling */
.navbox-abovebelow,
.navbox-group,
.navbox-subgroup .navbox-title {
    background: #fff;
    border: 1px solid #aaa;
    color: #000;
}

/* Level 3 styling */
.navbox-subgroup .navbox-group,
.navbox-subgroup .navbox-abovebelow {
    background: #fff;
    border: 1px solid #aaa;
    color: #000;
}

/* Even row striping */
.navbox-even {
    background: #e2e2e2;
    color: #000;
}

/* Odd row striping */
.navbox-odd {
    background: transparent;
}

.collapseButton {
    font-weight: normal;
    width: auto;
}

.navbox .collapseButton {
    width: 6em;
}

.navbar {
    font-size: 88%;
    font-weight: normal;
}

.navbox .navbar {
    font-size: 100%;
}

table.collapsed tr.collapsible {
    display: none;
}
/* End of new Navbox styling */

#fptopsection {
    padding-bottom: 10px;
}

/* This governs the sections on the Community portal */
.cpbox {
    display: flex;
    flex-direction: row-reverse;
    flex-wrap: wrap;
}

.cpbox #admins {
  box-sizing: border-box;
  width: calc(33% - 10px);
  margin: 5px;
  flex-grow: 1;
  min-width: 300px;
}

.cpbox #help {
  box-sizing: border-box;
  width: calc(67% - 10px);
  margin: 5px;
  flex-grow: 1;
}

.feature {
    background: rgba(0, 0, 0, 0.05);
    border: 1px solid rgba(0, 0, 0, 0.2);
    border-radius: 5px; padding: 10px;
}

