/* Newer Navbox template style */
table.navbox {
    border: 1px solid #aaa;
    clear: both;
    font-size: 88%;
    margin: auto;
    padding: 1px;
    text-align: center;
    width: 100%; 
}

/* Border between adjacent navboxes */
table.navbox + table.navbox {
    margin-top: -1px;
}

.navbox-title,
.navbox-abovebelow,
table.navbox th {
    padding-left: 1em;
    padding-right: 1em;
    text-align: center;
}

.navbox-group {
    font-weight: bold;
    padding-left: 1em;
    padding-right: 1em;
    white-space: nowrap;
}

/* Base background */
.navbox, .navbox-subgroup {
    background: #fff;
}

.navbox-list {
    border-color: #fff;   /* Must match background color */
}

/* Level 1 color */
.navbox-title,
table.navbox th {
    background: #fff;
    border: 1px solid #aaa;
    color: #000;
}

/* Level 2 styling */
.navbox-abovebelow,
.navbox-group,
.navbox-subgroup .navbox-title {
    background: #fff;
    border: 1px solid #aaa;
    color: #000;
}

/* Level 3 styling */
.navbox-subgroup .navbox-group,
.navbox-subgroup .navbox-abovebelow {
    background: #fff;
    border: 1px solid #aaa;
    color: #000;
}

/* Even row striping */
.navbox-even {
    background: #e2e2e2;
    color: #000;
}

/* Odd row striping */
.navbox-odd {
    background: transparent;
}

.collapseButton {
    font-weight: normal;
    width: auto;
}

.navbox .collapseButton {
    width: 6em;
}

.navbar {
    font-size: 88%;
    font-weight: normal;
}

.navbox .navbar {
    font-size: 100%;
}

table.collapsed tr.collapsible {
    display: none;
}
/* End of new Navbox styling */

/* CSS placed here will be applied to all skins */
/* This governs the sections on the Community portal */
.cpbox {
    display: flex;
    flex-direction: row-reverse;
    flex-wrap: wrap;
}

.cpbox #admins {
  box-sizing: border-box;
  width: calc(33% - 10px);
  margin: 5px;
  flex-grow: 1;
  min-width: 300px;
}

.cpbox #help {
  box-sizing: border-box;
  width: calc(67% - 10px);
  margin: 5px;
  flex-grow: 1;
}

/* Template documentation styles */
/* If modifying these styles, be sure to update the mobile skin! */
.doc {
    margin: 0em auto 1em;
    background-color: rgba(0, 0, 0, 0.1);
    border: 2px solid #BDCAC3;
    border-radius: 1em;
    padding: 1em;
}

.doc-header {
    padding-bottom: 3px;
