/* CSS placed here will affect users of the Hydra skin */

/* For elements which only display in the mobile view */
.mobileonly {
    display: none;
}

/* Hide main page header */
body.page-Gears_Pop_Wiki h1.firstHeading {
    display:none;
}

/* Framework */
body {
   background: url(https://static.wikia.nocookie.net/gearspop_gamepedia_en/images/a/ad/Gears-pop-background.jpg/revision/latest);
   background-size: cover;
   background-position: top center;
   background-repeat: no-repeat;
   background-attachment: fixed;
   background-color: #771700;
}

body #pageWrapper {
    margin-right: 5px;
}

/* Head */
#mw-head-base {
    background: transparent;
    background-image: none;
    border-bottom: 0px;
}

div#mw-page-base {
    background: transparent;
    background-image: none;
}

#mw-head li.new a {
    color: #db9fc9;
}

/* Logo */
#p-logo,
#p-logo a {
    height: 120px !important;
    width: 350px !important;
}

#p-logo {
    left: 50vw;
    margin-left: -186px;
    margin-top: 15px;
}

#p-logo a {
	display: block;
	width: 10em;
	height: 160px;
	background-repeat: no-repeat;
	background-position: center center;
	text-decoration: none;
	background-size: 100%;
	margin-top: 15px;
}

.mw-wiki-logo {
    -webkit-filter: drop-shadow(0px 0px 10px white);
    filter: drop-shadow(0px 0px 3.5px white) drop-shadow(1px 1px 1px white);
}

/* Tabs */
#left-navigation {
    margin-top: 150px;
}

#right-navigation {
    margin-right: 5px;
    margin-top: 150px;
}

div.vectorTabs {
    background-color: rgba(0,0,0,0);
    background-image: none;
    height: 33px;
    margin-top: 8px;
}

div#mw-head a,
.vectorTabs li a span,
div#mw-head div.vectorTabs a,
div.vectorMenu h3 span {
    color: white;
    font-weight: bold;
}

div.vectorMenu h3 span {
    padding-top: 0.2em;
}

div.vectorMenu h3 span::after {
    right: -5px;
    top: 0;
}

div.vectorTabs li a {
    background-image: none;
    margin-top: -16px;
}

div.vectorTabs li.new a,
div.vectorTabs li.new a:visited {
    color: black;
}

div.vectorTabs li span {
    background: #820000;
    display: inline-block;
    border: 1px solid #820000;
    border-radius: 4px;
    padding: 2px 5px;
    margin: 0 3px 2px;
    height: 19px;
    text-align: center;
}

div.vectorTabs span {
    background-color: rgba(0, 0, 0, 0);
    background-image: none;
}

div.vectorTabs li.selected {
    background-color: rgba(0, 0, 0, 0);
    background-image: none;
    color: white;
}

div.vectorTabs ul { 
    background-color: rgba(0, 0, 0, 0);
    background-image: none;
}

div.vectorTabs ul li {
    background-color: rgba(0, 0, 0, 0);
    background-image: none;
}

div.vectorTabs li a,
div.vectorTabs li a span {
    color: white;
    cursor: pointer;
    font-weight: bold;
}

div.vectorTabs li.selected a,
div.vectorTabs li.selected a:visited {
    color: white;
    text-decoration: none;
    font-weight: bold;
}

div.vectorMenu div.menu {
    border-color: inherit;
}

div.vectorMenu h3 a {
    background-color: rgba(0, 0, 0, 0);
    background-image: none;
    border: 0px;
}

div#mw-head div.vectorMenu li a {
    color: white;
}

div#mw-head div.vectorMenu li a:hover {
    color: white;
}

div#mw-head div.vectorMenu ul {
    background-color: #820000;
    background-image: none;
    border: 1px solid #820000;
}

div#mw-head div.vectorMenu h3 {
    background-image: none;
}

div#mw-head div.vectorMenu h3 {
    background: #820000;
    display: inline-block;
    border: 1px solid #820000;
    border-radius: 4px;
    color: white;
    font-weight: bold;
    padding: 2px 10px;
    margin-top: 8px;
    height: 19px;
    text-align: center;
    margin-bottom: 0.5em;
}

div.vectorMenu h3 a {
    background-color: rgba(0, 0, 0, 0);
    background-image: url("https://static.wikia.nocookie.net/commons_hydra/images/8/80/Vector_menu_downarrow_white.png");
    background-position: 50% 50%;
    border: medium none;
}

div#mw-head div.vectorMenu h4,
div#p-variants.vectorMenu #mw-vector-current-variant {
    color: white;
    font-weight: bold;
    padding-top: 0.2em;
    text-shadow: none;
}

.vectorTabs #ca-watch span,
.vectorTabs #ca-unwatch span {
    background: #820000; -moz-linear-gradient(center top , #1f3042 35%, #1f3042 100%) repeat scroll 0 0;
    border-radius: 4px;
}

.vectorTabs #ca-unwatch.icon a,
.vectorTabs #ca-watch.icon a {
    padding-top: 18px;
}

/* Sidebar */
div#mw-panel {
    margin-top: -15px;
}

div#mw-panel div.portal:not(#p-claimWiki):not(#p-socialProfiles):not(#p-sitePromos) {
    background: rgba(255, 255, 255, 0.7);
    box-shadow: 0 0.1em 0.75em #D5D4D4;
    border: none;
    border-radius: 5px 5px 5px 5px;
    margin: 5px;
    padding-top: 5px;
}

div#mw-panel div.portal div.body,
#mw-panel.collapsible-nav .portal {
    background-image: none;
}

div#mw-panel div.portal div.body ul li a,
div#mw-panel div.portal div.body ul li a:visited {
    color: #000000;
}

div#mw-panel div.portal h3,
div#mw-panel div.portal h3:visited,
#mw-panel.collapsible-nav .portal h3 a,
#mw-panel.collapsible-nav .portal h3 a:visited,
#mw-panel.collapsible-nav .portal.collapsed h3 a,
#mw-panel.collapsible-nav .portal.collapsed h3 a:visited {
    color: #820000;
    font-weight: bold; 
    text-transform: uppercase;
    font-family: "Caudex-Bold";
}

div#mw-panel div#p-socialProfiles.portal .body {
    margin: auto;
}

.socialSidebar {
    width: auto;
    max-width: 100%;
}

/* Content */
div#content {
    background: rgba(255, 255, 255, 0.7);
    box-shadow: 0 0.1em 0.75em #D5D4D4;
    border: none;
    border-radius: 5px;
    box-sizing: border-box;
    color: #000000;
    margin-top: 6.5em;
}

/* anchors */
a, 
a:visited,
div#content a.extiw,
div#content a.extiw:visited,
div#content a.external, 
div#content a.external:visited {
    color: #820000;
    font-weight: bold;
}

/* headers */
.mw-body h1, 
.mw-body h2 {
        border-bottom: 1px solid #820000;
       font-family: "Caudex-Bold";
}

h1, h2, h3, h4, h5, h6 {
        font-family: "Caudex-Bold";
	color: #820000;
        border-bottom: 1px solid #820000;
	background: none;
	font-weight: normal;
	margin: 0;
	overflow: hidden;
	padding-top: 0.5em;
	padding-bottom: 0.17em;        
}

.catlinks,
ul#filetoc {
    background: rgba(0, 0, 0, 0);
    border: 1px solid #820000;
    border-radius: 5px;
    clear: both;
    margin-top: 1em;
    padding: 5px;
}

.catlinks li {
    border-left: none;
}

.CategoryTreeToggle {
    color: #3b82b9;
}

#toc, .toc,
.mw-warning {
    background-color: rgba(0, 0, 0, 0);
    border: 1px solid #3c83ba;
    border-radius: 5px;
    box-shadow: 0 0.1em 0.75em #000000;
}

div.mw-warning-with-logexcerpt {
    border: 2px solid #3c83ba;
}

fieldset {
    border: 1px solid #820000;
    border-radius: 5px;
}

ul {
    list-style-image: none;
}

/* Footer */
div#footer {
    background: rgba(255, 255, 255, 0.7);
    box-shadow: 0 0.1em 0.75em #D5D4D4;
    border: none;
    border-radius: 5px;
    margin-bottom: 5px;
    margin-top: 5px;
}

div#footer ul li {
    color: #000000;
}

div#footer ul li a {
    color: #820000;
}

/* WikiClaims tool dropdown fix */
#claimlist .controls_container > .dropdown {
    right: 24px;
    top: -24px;
}

/* tables */
table.wikitable {
    background: none repeat scroll 0 0 transparent;
}

table.wikitable > caption {
    color: #000000;
}

table.wikitable > tr > th,
table.wikitable > * > tr > th {
    background: #820000;
    border: 1px solid black;
    color: #FFFFFF;
    text-align: center;
}

table.wikitable > tr > td,
table.wikitable > * > tr > td {
    border: 1px solid black;
    padding: 0.2em;
}

.wikitable th {
    background-color: #820000;
    border: 1px solid black;
    color: #FFFFFF;
    padding: 0.2em;
}

.wikitable td {
    border: 1px solid black;
    color: #000000;
    padding: 0.2em;
}

table.mw_metadata th {
    background: #820000;
    border: 1px solid black;
    color: #FFFFFF;
}

table.mw_metadata td {
    background-color: transparent;
    border: 1px solid black;
    color: #000000;
}

.mw-datatable th {
    border: 1px solid black;
}

.mw-datatable,
.mw-datatable td {
    border: 1px solid black;
}

.TablePager {
    border:1px solid black;
    color: #000000;
    padding:0 0.15em;
}

.TablePager th {
    background-color: #820000;
    color: #ffffff;
    border:1px solid black;
    padding:0 0.15em;
}

.TablePager tr:hover td {
    background-color: rgba(0, 0, 0, 0.2) !important;
    color: #FFFFFF;
}

.TablePager th a {
    background-color: #820000;
    color: #FFFFFF !important;
}

.TablePager td {
    background: transparent !important;
    border: 1px solid black;
    color: #000000;
}

/* sorting arrows */
table.jquery-tablesorter th.headerSort {
	background-image: url(https://static.wikia.nocookie.net/commons_hydra/images/3/36/Sort_both_white.gif);
	background-image: linear-gradient(transparent,transparent),url(https://static.wikia.nocookie.net/commons_hydra/images/3/36/Sort_both_white.gif);
	background-image: -o-linear-gradient(transparent,transparent),url(https://static.wikia.nocookie.net/commons_hydra/images/3/36/Sort_both_white.gif);
	cursor: pointer;
	background-repeat: no-repeat;
	background-position: center right;
	padding-right: 21px;
}

table.jquery-tablesorter th.headerSortUp {
	background-attachment: scroll;
	background-image: url(https://static.wikia.nocookie.net/commons_hydra/images/8/82/Sort_up_white.gif);
	background-image: linear-gradient(transparent,transparent),url(https://static.wikia.nocookie.net/commons_hydra/images/8/82/Sort_up_white.gif);
	background-image: -o-linear-gradient(transparent,transparent),url(https://static.wikia.nocookie.net/commons_hydra/images/8/82/Sort_up_white.gif);
	background-repeat: no-repeat;
	background-position: center right;
	padding-right: 21px;
}

table.jquery-tablesorter th.headerSortDown {
	background-attachment: scroll;
	background-image: url(https://static.wikia.nocookie.net/commons_hydra/images/5/56/Sort_down_white.gif);
	background-image: linear-gradient(transparent,transparent),url(https://static.wikia.nocookie.net/commons_hydra/images/5/56/Sort_down_white.gif);
	background-image: -o-linear-gradient(transparent,transparent),url(https://static.wikia.nocookie.net/commons_hydra/images/5/56/Sort_down_white.gif);
	background-repeat: no-repeat;
	background-position: center right;
	padding-right: 21px;
}

/* Interwiki page legend tweak */
.mw-collapsible-toggle.mw-collapsible-toggle-expanded a,
.mw-collapsible-toggle.mw-collapsible-toggle-collapsed a {
    color: #ffffff;
}

/* colour fix for advanced search options box */
fieldset#mw-searchoptions {
    background-color: rgba(0, 0, 0, 0);
    border-color: #820000 !important;
}

.mw-search-profile-tabs {
    background-color: rgba(0, 0, 0, 0);
    border: 1px solid #820000;
    margin-top: 1em;
}

.mw-search-profile-tabs div.search-types ul li.current a {
    color: #000000;
}

/* Page history */
#pagehistory li {
    background-color: rgba(0, 0, 0, 0);
    border: none;
    padding: 3px;
}

#pagehistory li.selected {
    background-color: rgba(255, 255, 255, 0.5);
    background-image: none;
    border: 1px dashed #820000;
    padding: 3px;
}

table.diff {
    background: transparent;
}

td.diff-context {
    background: none repeat scroll 0 0 transparent;
    color: #000000;
}

td.diff-deletedline {
    background-color: #FFE49C;
    border-color: #FFE49C;
    color: #000000;
}

td.diff-addedline {
    background-color: #A3D3FF;
    border-color: #A3D3FF;
    color: #000000;
}

/* thumbnails and galleries and image file history */
div.thumb {
    border: 1px solid #820000;
    margin: 2px;
    margin-left: 6px;
}

img.thumbborder {
    border: 1px solid #820000;
    border-radius: 5px;
    padding: 5px;
}

div.thumbinner {
    background-color: rgba(255, 255, 255, 0.2);
    border: medium none;
}

li.gallerybox div.thumb {
    background-color: rgba(255, 255, 255, 0.2);
    border: 1px solid #820000;
    border-radius: 5px;
}

html .thumbimage {
    border: 1px solid #820000;
    border-radius: 5px;
}

div.tright div.tleft {
    border: 1px solid #820000 !important;
}

div.tright {
    clear: right;
    float: right;
}

/* Preferences */
.client-js #preftoc {
    background-color: rgba(255, 255, 255, 0.5);
    border: 0px;
    margin: 0 0 4px !important;
}

.client-js #preftoc,
.client-js #preftoc li,  
.client-js #preferences, 
.client-js #preftoc li a {
    background-image: none;
    background-color: transparent;
    color: #666666;
}

.client-js #preftoc li:first-child {
    margin-bottom: 0;
    margin-left: 5px;
}

.client-js #preftoc li.selected a {
    background-color: #820000;
    background-image: none;
    border-color: #820000 #820000 #820000;
    border-radius: 5px 5px 0 0;
    border-style: solid;
    border-width: 1px;
    color: white;
}

.client-js #preferences {
    background-color: rgba(255, 255, 255, 0.5);
    border: 1px solid #820000;
    border-radius: 5px;
}

.client-js #preferences fieldset {
    border-color: #820000;
}

/* wiki editor styling */
.wikiEditor-ui {
    background: rgba(0, 0, 0, 0);
    border: none;
}

.wikiEditor-ui-tabs div {
    border-bottom: 1px solid #820000;
    border-right: 1px solid #820000;
}

.wikiEditor-ui-buttons {
    background: rgba(0, 0, 0, 0);
    border-top: none;
    margin-right: 5px;
}

.wikiEditor-ui-toolbar {
    background: none repeat scroll 0 0 rgba(0, 0, 0, 0);
}

.wikiEditor-ui-toolbar .tabs span.tab a,
.wikiEditor-ui-toolbar .tabs span.tab a:visited {
    color: #000000;
}

.wikiEditor-ui-toolbar .tabs span.tab a.current,
.wikiEditor-ui-toolbar .tabs span.tab a.current:visited {
    color: #000000;
    font-weight: bold;
}

.wikiEditor-ui-toolbar .sections .section {
    background-color: rgba(0, 0, 0, 0.2);
    border-top: 1px solid #820000;
    color: #000000;
}

.wikiEditor-ui-toolbar .page-characters div span {
    border: 1px solid #820000;
    color: #000000;
}

.wikiEditor-ui-toolbar .booklet .pages {
    background-color: rgba(255, 255, 255, 0.2);
}

.wikiEditor-ui-toolbar .booklet .index .current {
    background-color: rgba(255, 255, 255, 0.2);
    color: #0645ad;
}

.wikiEditor-ui-toolbar .booklet .index div {
    color: #000000;
}

.wikiEditor-ui-toolbar .page-characters div span:hover {
    background-color: rgba(255, 255, 255, 0.2);
    border-color: #820000;
    color: #ffffff;
}

.wikiEditor-ui-toolbar .page-table th,
.wikiEditor-ui-toolbar .page-table td {
    color: #000000;
}

.wikiEditor-ui-toolbar .page-table td {
    border-top: 1px solid #820000;
}

.wikiEditor-ui-tabs div a {
    background: none repeat scroll 0 0 #820000;
    display: inline-block;
    color: #FFFFFF;
}

.wikiEditor-ui-tabs div.current {
    border-bottom: 1px solid #820000;
}

.wikiEditor-ui-tabs div.current a {
    color: #ffffff;
    font-weight: bold;
}

.wikiEditor-ui-tabs {
    border-left: 1px solid #820000;
    border-top: 1px solid #820000;
}

.wikiEditor-preview-contents {
    background: rgba(0, 0, 0, 0);
    background-color: rgba(255, 255, 255, 0.2);
    border-color: #820000;
    border-style: solid;
    border-width: 0 1px 1px;
    color: #000000;
}

.wikiEditor-ui-controls {
    background: rgba(0, 0, 0, 0);
    border-bottom: 1px solid #820000;
}

.wikiEditor-preview-contents,
.wikiEditor-preview-loading {
    background-color: transparent;
}

.editOptions {  
    background-color: rgba(255, 255, 255, 0.2);
    border-color: -moz-use-text-color #4ba5ec #4ba5ec;
    border-image: none;
    border-radius: 0 0 5px 5px;
    border-style: none solid solid;
    border-width: medium 1px 1px;
}

input#wpSummary {
    margin-bottom: 1em;
    margin-top: 1em;
    width: 80%;
}

/* for "edit this page" tab and "discussion" tab etc */
.pagetab {
     border-style: solid solid none;
     border-width: thin;
     border-color: #808080;
     padding:0.25ex 1ex 0ex;
     font-size: 95%;
}

.ambox {
    background-color: #eeeeee;
    border-bottom-color: #383838;
    border-right-color: #383838;
    border-top-color: #383838;
    border-collapse: collapse;
    font-size: 95%;
    margin: 0 auto 2px auto;
    width: 80%;
}

.ambox-gray {
    border-left-color: #383838;
}

.ambox.ambox-tiny {
    font-size: 90%;
    margin: 2px 0;
    width: auto;
}

.ambox + .ambox {
     margin-top: -2px;
}

.ambox-text {
     padding: 0.25em 0.5em;
}

.ambox-image {
     padding: 2px 0px 2px 0.5em;
     text-align: center;
     width: 60px;
}

.ambox-tiny .ambox-image {
     padding: 2px 0.5em;
     text-align: left;
     width: auto;
}

/* Ambox colors */
.ambox-blue {
     border-left: 10px solid #1e90ff;
}

.ambox-red {
     border-left: 10px solid #b22222;
}

.ambox-orange {
     border-left: 10px solid #f28500;
}

.ambox-yellow {
     border-left: 10px solid #f4c430;
}

.ambox-purple {
     border-left: 10px solid #9932cc;
}

.ambox-gray {
     border-left: 10px solid #bba;
}

.ambox-green {
     border-left: 10px solid #228b22;
}

/* Ambox small text */
.amsmalltext {
     font-size: smaller;
     margin-left:0.8em;
     margin-top:0.5em;
}

/* INFOBOXES */
.infoboxtable {
    background-color: #f9f9f9;
    border: 1px solid #820000;
    color: #000000;
    float: right;
    font-size: 89%; 
    margin-bottom: 0.5em; 
    margin-left: 1em; 
    padding: 0.2em; 
    width: 300px;
}

.infoboxtable td {
    vertical-align: top;
}

.infoboxtable td > div {
    background-color: #820000;
    border: 2px solid inherit; 
    border-radius: 5px; 
    font-weight: bold;
    padding: 0.5px 7px;
    text-align: right;
    color:white;
}

.infoboxname {
    font-size: 110%; 
    font-weight: bold;
    padding: 0.5em; 
}

.infoboxdetails {
    padding: 0em;
}

/* copyright images tweak */
.copyright-icon {
    background: url("https://static.wikia.nocookie.net/commons_hydra/images/thumb/b/b6/Copyright.png/32px-Copyright.png") transparent center center no-repeat;
    background-size: 100%;
    width: 32px;
    height: 32px;
}

.feature {
    background: rgba(0, 0, 0, 0.05);
    border: 1px solid rgba(0, 0, 0, 0.2);
    border-radius: 5px; padding: 10px;
}

/* Navbox template style */
table.navbox {
    border: 1px solid #aaaaaa;
    clear: both;
    font-size: 88%;
    margin: auto;
    padding: 1px;
    text-align: center;
    width: 100%; 
}

/* Border between adjacent navboxes */
table.navbox + table.navbox {
    margin-top: -1px;
}

.navbox-title,
.navbox-abovebelow,
table.navbox th {
    padding-left: 1em;
    padding-right: 1em;
    text-align: center;
}

.navbox-group {
    font-weight: bold;
    padding-left: 1em;
    padding-right: 1em;
    white-space: nowrap;
}

/* Base background */
.navbox, .navbox-subgroup {
    background: rgba(255, 255, 255, 0.2);
}

.navbox-list {
    border-color: rgba(255, 255, 255, 0.2); /* Must match background color */
}

/* Level 1 color */
.navbox-title,
table.navbox th {
    background: rgba(255, 255, 255, 0.2);
    color: #444;
}

/* Level 2 styling */
.navbox-abovebelow,
.navbox-group,
.navbox-subgroup .navbox-title {
    background: rgba(255, 255, 255, 0.2);
    color: #333;
}

/* Level 3 styling */
.navbox-subgroup .navbox-group,
.navbox-subgroup .navbox-abovebelow {
    background: rgba(0, 0, 0, 0.05);
    color: #333;
}

/* Even row striping */
.navbox-even {
    background: rgba(0, 0, 0, 0.05);
    color: #333;
}

/* Odd row striping */
.navbox-odd {
    background: transparent;
}

.collapseButton {
    font-weight: normal;
    width: auto;
}

.navbox .collapseButton {
    width: 6em;
}

.navbar {
    font-size: 88%;
    font-weight: normal;
}

.navbox .navbar {
    font-size: 100%;
}

table.collapsed tr.collapsible {
    display: none;
}
/* End of new Navbox styling */

/* this CSS governs the responsive 2 column main page layout */

.fpcontent {
    width: 100%;
    overflow: hidden;
    z-index: 1;
}

.fpmaybecols {
    overflow: hidden;
    margin: -5px 0 -5px 0;
}

.fpmaybecols + .fpmaybecols {
    margin: 0 0 -5px 0;
}

.fpbox {
    background: rgba(255, 255, 255, 0.5);
    border-radius: 5px;
    border: none;
    color: #505050; /* change for hydra (light) wikis */
    margin: 5px 5px 5px 5px;
    padding: 5px 5px 5px 5px;
    box-shadow: 0 0.1em 0.75em #820000;
}

.fpbox2 {
	background-size: 60%;
	background-position: -50px -20px;
	background-repeat: no-repeat;
	background-attachment: scroll;
	background-color: rgba(255,255,255,0.5);
	border-radius: 5px;
	border: none;
	color: #505050;
	margin: 5px 5px 5px 5px;
	padding: 5px 5px 5px 5px;
	box-shadow: 0 0.1em 0.75em #820000;
}

.fpplainbox {
    padding: 5px 8px 10px 8px;
    margin: 0 5px 10px 5px;
    vertical-align: top;
}

.fpbox2 .welcome {
    border-bottom: none;
    color: #820000; /* change for hydra (light) wikis */
    font-size: 150%;
    margin: 0 0 10px 0;
    padding: 0 0 5px 0;
    font-family: "Caudex-Bold";
    text-transform: uppercase;
    text-align: center;
}

.fpbox .heading {
    background-color: #820000;
    border: none;
    color: white; /* change for hydra (light) wikis */
    font-size: 132%;
    font-family: "Caudex-Bold";
    text-transform: uppercase;
    margin: 0 0 10px 0;
    padding: 0 0 5px 0;
}

.fpbox .heading .smalllink {
    color: #820000; /* change for hydra (light) wikis */
    font-size: 75%;
    font-weight: bold;
}

.fpbox hr {
    border: none;
    border-bottom: 2px solid #505050;
}

.fplinks {
    margin: -5px;
}

.fplinks .linkslabel {
    background: rgba(0, 0, 0, 0);
    border-bottom: 2px solid #505050;
    margin: 15px 5px 5px 5px;
    padding: 0 0 5px 0;
}

.fplink {
    display: inline-block;
    vertical-align: middle;
    width: 100%;
    box-sizing: border-box;
    padding: 1px 5px;
}

.fplink .box {
    display: flex;
