.fpvideo iframe {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

.fpbox .bigmobilelinks .rightcol {
  padding: 0.25em 0 0 0;
}

@media (min-width: 400px) {
  .fpbox .bigmobilelinks .rightcol {
    padding: 0;
  }
}

.fpbox .bigmobilelinks ul, 
.fpbox .bigmobilelinks .leftcol ul, 
.fpbox .bigmobilelinks .rightcol ul {
  list-style: none;
  margin: 0;
  padding: 0 15px;
}

.fpbox .bigmobilelinks ul ul, 
div#content .fpbox .bigmobilelinks .leftcol ul ul, 
div#content .fpbox .bigmobilelinks .rightcol ul ul {
  list-style: none;
  padding: 0.25em 1em 0 1em;
}

.fpbox .bigmobilelinks ul li div {
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(128, 128, 128, 0.1);
  min-height: 4em;
  margin: 0.25em 0;
  padding: 0;
}

.fpbox .bigmobilelinks a {
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(128, 128, 128, 0.2);
  min-height: 4em;
  margin: 0.25em 0;
  padding: 0;
}

div.cpbox div.feature {
  width:unset !important;
}

/* Classes permitting setting of alignment on mobile only or differently on desktop and mobile */
/* (See .desktopleft, .desktopcenter, .desktopright in MediaWiki:Common.css for the desktop equivalents */
.mobileleft {
  text-align: left;
}

.mobilecenter {
  text-align: center;
}

.mobileright {
  text-align: right;
}

/* CSS placed here will affect users of the mobile site */

/* Header and footer */
.header-container.header-chrome,
#mw-mf-page-center {
    background: transparent;
}

.header .branding-box h1 {
    border-bottom: none;
}

.nomobile {
    display: none;
}

a.watch-this-article {
    background-image: url("http://commons.gamepedia.com/media/commons.gamepedia.com/7/7b/Watch_lighter.png") !important; /* optional if a lighter version of the star icon is required */
}

/* search header */
.pre-content #page-actions {
    background: rgba(0, 0, 0, 0.85) !important;
}

.overlay .overlay-header-container {
    background: rgba(0, 0, 0, 0.85) !important;
}

.search-overlay .overlay-header,
.search-overlay .results {
    background-color: rgba(0, 0, 0, 0.85) !important;
    color: #c0c0c0;
}

.search-overlay {
    background: none repeat scroll 0 0 rgba(0, 0, 0, 0.5) !important; 
}

ul.suggestions-results,
ul.suggestions-results li {
    background: rgba(0, 0, 0, 0.85);
    color: #c0c0c0;
}

ul.suggestions-results li.suggestions-result {
    color: #c0c0c0;
}

/* general header *
#mw-mf-header form,
#mw-mf-sq {
    background: rgba(0, 0, 0, 0.85);
}

/* non-content area */
body {
    background: #000 url("https://d1u5p3l4wpay3k.cloudfront.net/gearspop_gamepedia_en/a/ad/Gears-pop-background.jpg?version=f47a96b2be68822b369bbcdd55d36a5e") no-repeat fixed center 30px / 100% auto;
    color: white;
}

.overlay-enabled,
#content {
    background: rgba(0, 0, 0, 0.7);
    color: white;
}

footer {
    border-top: 1px solid #666668;
    color: #ffffff;
    text-shadow: 1px 1px #000000;
}

footer a {
    color: #fefeee;
    text-shadow: 1px 1px #000000;
}

footer h2 {
    color: #fefeee;
    text-shadow: 1px 1px #000000;
}

/* content area */
a,
a.external {
    color: #9db4c2;
}

.content table th {
    background-color: rgba(0, 0, 0, 0);
}

.content table td,
.content table th {
    border: medium none;
    padding: 3px;
}

h1, 
h2 {
    background: none repeat scroll 0 0 rgba(0, 0, 0, 0);
    border-bottom: 1px solid white;
    color: white;
}

h3, h4, h5, h6 {
    background: none repeat scroll 0 0 rgba(0, 0, 0, 0);
    color: white;
}

.thumb,
#content_wrapper .thumb {
    background: transparent;
    border: 2px solid rgba(0, 0, 0, 0.2);
}

table.wikitable {
    border: none;
    border-collapse: separate !important;
    border-spacing: 2px !important;
    margin: auto;
    margin-bottom: 1em;
}

table.wikitable td {
    border: none;
    padding: 3px;
    background: rgba(0, 0, 0, 0);
}

table.wikitable th {
    background: rgba(0, 0, 0, 0);
    border: none;
    padding: 3px;
}

.mwm-notice,
#searchbox {
    background: rgba(0, 0, 0, 0);
    border: 2px solid rgba(0, 0, 0, 0.2);
    border-radius: 5px 5px 5px 5px;
}

.divclearable,
a.watch-this-article,
.jsEnabled #mw-mf-main-menu-button {
    background-color: rgba(0, 0, 0, 0);
}

a.back_to_top,
a.back_to_top:visited {
    margin-top: 7px;
}

a:visited {
    color:#919e6d;
}

/* Fix black on black section arrows */
.mw-ui-icon-arrow::before {
    filter: invert(100%);
}

ul.gallery, li.gallerybox {
  background-color: transparent;
  border-color: transparent;
}

li.gallerybox div.thumb {
  background-color: #181818;
  border-color: #303030;
}

#action-table tr td .action-image {
  position: relative;
  padding: 5px;
  background-color: #1f3850;
  border: #46ffdd 1px solid;
  border-radius: 3px;
}

#action-table tr td .animated {
  position: absolute;
  top: -1px;
  left: -1px;
  z-index: 1;
  line-height: 1.1em;
  padding:0 1px 0 1px;
  color: #46ffdd;
  border: #46ffdd 1px solid;
  border-radius: 3px;
}

/* Tablet */
@media screen and (min-width: 600px) {
  #action-table tr td .animated {
    font-size: 75%;
    padding: 1px 1px 0 1px;
  }
}

/* Table layout for phones */
@media screen and (max-width: 600px) and (orientation:portrait) {
    #action-table {
      border: 0;
    }

    #action-table thead, #action-table th {
      display: none;
    }

    #action-table tr {
      margin-bottom: 15px;
      display: block;
      float: left;
    }

    #action-table td {
      display: block;
      text-align: left;
      border: none;
      float: left;
      clear: right;
      width: 70%;
      padding: 0;
    }

    #action-table td:first-child {
      display: inline-block;
      border: none;
      float: left;
      clear: none;
      width: 23%;
      padding-right: 5px;
    }

    #action-table td:last-child {
      min-height: 26px;
      text-align: right;
      float: left;
      width: 98%
    }

    #action-table td:last-child:before {
      content: attr(data-label);
      float: left;
      font-weight: bold;
    }
}

.globalNotice {
 color: white;
}

.header {
    background-color: #1f3042;
    border: #1f3042;
    box-shadow: none;
    color: #FFFFFF;
    font-size: 150%;
    margin-bottom: 10px;
    text-align: center;
}

img.percentage {
width: 95%;
height: auto;
padding-top:1%;
}

/*********************
/* Front page styles *
/*********************/
.fpmain {
  width: 100%;
  overflow: hidden;
  z-index: 1;
}

.fpbanner {
  border: 1px solid #1f3042;
  box-shadow: 0 2px 5px #1f3042;
  background: rgba(0, 0, 0, 0.25);
  color: #9ccad2;
  margin: 0 5px 5px 5px;
  padding: 5px;
  min-height: 80px;
}

.fpbannertable {
  display: table;
  border: none;
  background: transparent;
  width: 100%; 
  min-height: 75px;
  margin: 0;
  padding: 5px;
}

.fpbannercell {
  display: table-cell; 
  text-align: center; 
  vertical-align: middle;
}

.fpbannerblock {
  border: none;
  color: #ffffff;
  font-weight: bold;
  text-shadow: 0 0 8px rgba(255, 255, 255, 0.75);
  font-size: 132%;
  width: 100%;
  margin: 0 0 10px 0;
  padding: 0 0 5px 0;
}


.fpmidsections {
  float: left;
  width: 100%;
  overflow: hidden;
}

.fpbox {
  border: 1px solid #1f3042;
  background: rgba(0, 0, 0, 0.25);
  color: white;
  margin: 5px 5px 5px 5px;
  padding: 5px 5px 5px 5px;
  overflow: auto;
}

.fpbox .mainheading {
  border: none;
  border-bottom: 1px solid #1f3042;
  color: #ffffff;
  font-size: 150%;
  font-weight: bold;
  margin: 0 0 10px 0;
  padding: 0 0 5px 0;
  overflow: auto;
}

.fpbox .heading {
  border: none;
  border-bottom: 1px solid #1f3042;
  color: #ffffff;
  font-size: 132%;
  margin: 0 0 10px 0;
  padding: 0 0 5px 0;
  overflow: auto;
}

.fpmain .columns .leftcol {
  width: 100%;
  margin: 0;
  padding: 0;
}

.fpmain .columns .rightcol {
  width: 100%;
  margin: 0;
  padding: 0;
}

.fpsection1, .fpsection2, .fpsection3, .fpsection4 {
  float: left;
  clear: both; 
  width: 100%;
}

div.fp2columnonly, div.fp3columnonly {
  display: none; 
}

@media (min-width: 790px) {
  .fpsection1 {
    float: left;
    clear: none;
    width: 50%;
  }

  .fpmidsections {
    clear: none;
    float: right;
    width: 50%;
  }

  .fpsection4 {
    float: left;
    clear: none;
    width: 50%;
  }

  div.fp2columnonly {
    display: block; 
  }
}

@media (min-width: 990px) {
  .fpmain .columns .leftcol {
    float: left;
    width: 50%;
    margin: 0;
    padding: 0;
  }

  .fpmain .columns .rightcol {
    float: right;
    width: 50%;
    margin: 0;
    padding: 0;
  }
}

@media (min-width: 1390px) {
  .fpmidsections {
    clear: none;
    float: right;
    width: 66.667%;
  }

  .fpsection1 {
    clear: none;
    width: 33.333%;
  }

  .fpsection2 {
    clear: none;
    width: 50%;
  }

  .fpsection3 {
    clear: none;
    width: 50%;
  }

  .fpsection4 {
    clear: left;
    width: 33.333%;
  }

  div.fp2columnonly {
    display: none; 
  }

  div.fp3columnonly {
    display: block; 
  }
}

.fpbox.plain {
  border: none;
  box-shadow: none;
  background: transparent;
}

.fpimagelist ul {
  list-style-type: none;
  list-style-image: none;
}

.fpvideos {
  margin: 0 auto;
  overflow: hidden;
  text-align: center;
}

.fpvideo {
  display: inline-block;
  margin: 0 5px;
}

/* INFOBOXES: game or book depended color style */
.infoboxtable {
    background-color: transparent;
    border: 1px solid #1f3042;
    color: white;
    float: right;
    font-size: 89%; 
    margin-bottom: 0.5em; 
    margin-left: 1em; 
    padding: 0.2em; 
    width: 300px;
}

.infoboxtable td {
    vertical-align: top;
}

.infoboxtable td > div {
    background-color: transparent;
    border: 2px solid inherit; 
    border-radius: 5px; 
    font-weight: bold;
    padding: 0.5px 7px;
    text-align: left;
}

.infoboxname {
    background-color: #1f3042;
    border: 2px solid inherit; 
    color: white;
    font-size: 100%; 
    font-weight: bold;
    padding: 0.5em; 
}

.infoboxdetails {
    background: #1f3042;
    color: white;
}

.feature {
    background: rgba(0, 0, 0, 0.1);
    border: 1px solid rgba(0, 0, 0, 0.5);
    border-radius: 5px;
    padding: 10px;
}

.skin-hydradark div#mw-panel div.portal h3 {
    color: #c0c0c0;
}

.overlay-enabled, #content {
    background: rgba(0, 0, 0, 0.8);
}

