#action-table tr td .action-image {
  position: relative;
  padding: 5px;
  background-color: #1f3850;
  border: #46ffdd 1px solid;
  border-radius: 3px;
}

#action-table tr td .animated {
  position: absolute;
  top: -1px;
  left: -1px;
  z-index: 1;
  line-height: 1.1em;
  padding:0 1px 0 1px;
  color: #46ffdd;
  border: #46ffdd 1px solid;
  border-radius: 3px;
}

/* Tablet */
@media screen and (min-width: 600px) {
  #action-table tr td .animated {
    font-size: 75%;
    padding: 1px 1px 0 1px;
  }
}

/* Table layout for phones */
@media screen and (max-width: 600px) and (orientation:portrait) {
    #action-table {
      border: 0;
    }

    #action-table thead, #action-table th {
      display: none;
    }

    #action-table tr {
      margin-bottom: 15px;
      display: block;
      float: left;
    }

    #action-table td {
      display: block;
      text-align: left;
      border: none;
      float: left;
      clear: right;
      width: 70%;
      padding: 0;
    }

    #action-table td:first-child {
      display: inline-block;
      border: none;
      float: left;
      clear: none;
      width: 23%;
      padding-right: 5px;
    }

    #action-table td:last-child {
      min-height: 26px;
      text-align: right;
      float: left;
      width: 98%
    }

    #action-table td:last-child:before {
      content: attr(data-label);
      float: left;
      font-weight: bold;
    }
}

