/*********************
/* Front page styles *
/*********************/
.fpbox {
  border-radius: 5px;
  border: 2px solid #7c7c7c;
  box-shadow: 0 0 0 2px rgba(0, 0, 0, 0) inset;
  background: transparent;
  color: inherit;
  margin: 5px;
  padding: 5px;
}

.fpbox .welcome {
  border-bottom: 1px solid #505050;
  background: transparent;
  /* color: #e0e0e0; */
  font-size: 150%;
  text-transform: uppercase;
  text-align: center;
  margin: 0 0 10px 0;
  padding: 0 0 5px 0;
}

.fpbox .heading {
  border-bottom: 1px solid #505050;
  background: transparent;
  /* color: #e0e0e0; */
  font-size: 132%;
  font-variant: small-caps;
  margin: 0 0 10px 0;
  padding: 0 0 5px 0;
}

.fpbox .heading .smalllink {
  color: #3674b3;
  font-weight: bold;
  font-size: 75%;
}

.fpbox hr {
  border: none;
  border-bottom: 2px solid #505050;
}

.fpplainbox {
  padding: 5px 8px 10px 8px;
  margin: 0 5px 10px 5px;
  vertical-align: top;
}

.fplinks {
  margin: -2px -3px;
}

.fplinks .linkslabel {
  border-bottom: 2px solid #505050;
  margin: 6px 3px 0 3px;
}

.fplink {
  display: inline-block;
  vertical-align: middle;
  width: 100%;
}

/* Yeah, using display: table makes for a lot of extra markup, but it makes proportionate sizing and vertical centering a lot easier, so going with it */
.fplink .box {
  display: table;
  width: 100%;
  border-spacing: 2px 3px;
  border-collapse: separate;
}

.fplink .box .row {
  display: table-row;
}

.fplink .box .row .cell {
  background: rgba(0, 0, 0, 0) none repeat scroll 0 0;
  border: 2px solid #505050;
  border-radius: 2px;
  box-shadow: 0 0 0 2px #505050 inset;
  /* color: #e0e0e0; */
  display: table-cell;
  font-weight: bold;
  position: relative;
  text-align: center;
  text-transform: uppercase;
  vertical-align: middle;
}

.fplink.wide .box .row .cell {
  padding: 0 5px;
}

.fplink.image {
  width: 78px;
  height: 78px;
}

.fplink.image .box .row .cell {
  width: 70px;
  height: 70px;
  vertical-align: bottom;
}

.fplink.image .box .row .cell .image img {
  width: 70px;
  height: 70px;
}

@media (min-width: 188px) {
  .fplink {
    width: 50%;
  }

  .fplink.wide {
    width: 100%;
  }
}

@media (min-width: 294px) {
  .fplink {
    width: 33.333%;
  }

  .fplink.wide {
    width: 66.666%;
  }
}

@media (min-width: 400px) {
  .fplink {
    width: 25%;
  }

  .fplink.wide {
    width: 50%;
  }

  .fplink.image {
    width: 108px;
    height: 108px;
  }

  .fplink.image .box .row .cell {
    width: 100px;
    height: 100px;
  }

  .fplink.image .box .row .cell .image img {
    width: 100px;
    height: 100px;
  }
}

