  .fplink {
    width: 16.666%;
  }

  .fplink.wide {
    width: 33.333%;
  }
}

@media (min-width: 718px) {
  .fplink {
    width: 14.285%;
  }

  .fplink.wide {
    width: 28.571%;
  }
}

@media (min-width: 824px) {
  .fplink {
    width: 12.5%;
  }

  .fplink.wide {
    width: 25%;
  }
}

@media (min-width: 930px) {
  .fplink {
    width: 11.111%;
  }

  .fplink.wide {
    width: 22.222%;
  }
}

@media (min-width: 1036px) {
  .fplink {
    width: 10%;
  }

  .fplink.wide {
    width: 20%;
  }

  .fplink.image {
    width: 128px;
    height: 128px;
  }

  .fplink.image .box .row .cell {
    width: 120px;
    height: 120px;
